// Telegram sends every kind of update to one place. Only a human typing text
// should reach the agent.
//
// The chat id is used as the session id, so each person keeps one continuous
// conversation across messages rather than starting fresh every time.

// The agent will only accept real UUIDs, and it uses the session id to remember
// a conversation. Deriving them by hand keeps one Telegram chat on one session,
// so the agent follows the conversation instead of meeting a stranger every
// message. Node's crypto is not available inside this sandbox, so this is a
// plain FNV-1a hash spread over the four rounds a UUID needs.
const uuidFrom = (seed) => {
  let hex = '';
  for (let round = 0; round < 4; round += 1) {
    let hash = 0x811c9dc5;
    const salted = `${round}:${seed}`;
    for (let index = 0; index < salted.length; index += 1) {
      hash ^= salted.charCodeAt(index);
      hash = Math.imul(hash, 0x01000193) >>> 0;
    }
    hex += hash.toString(16).padStart(8, '0');
  }
  return [
    hex.slice(0, 8),
    hex.slice(8, 12),
    `4${hex.slice(13, 16)}`,
    `8${hex.slice(17, 20)}`,
    hex.slice(20, 32)
  ].join('-');
};

const message = $json.message && typeof $json.message === 'object' ? $json.message : {};
const chat = message.chat && typeof message.chat === 'object' ? message.chat : {};
const from = message.from && typeof message.from === 'object' ? message.from : {};

const text = typeof message.text === 'string' ? message.text.trim() : '';
const chatId = chat.id;

// Other bots are ignored for the same reason Slack's trigger ignored them: a
// reply arriving back as a new message would have the agent answering itself
// until the credit ran out.
const fromBot = from.is_bot === true;

if (fromBot || text.length === 0 || chatId === undefined) {
  return [{ json: { skip: true } }];
}

// /start is what Telegram sends when someone first opens a bot, and it is the
// first thing anybody does. Rather than passing the literal text '/start' to
// the agent, which it would answer oddly, it becomes a request to introduce
// itself — so the very first exchange is a useful one.
const asked = text === '/start'
  ? 'Introduce yourself in two sentences: say what you can help me with, and give me one example of something I could ask you right now.'
  : text.replace(/^\/ask\s+/i, '');

// Derived from the message id, so if Telegram re-sends an update the same
// request id comes back rather than a second answer.
const requestId = uuidFrom(`telegram-request:${String(message.message_id ?? Date.now())}:${String(chatId)}`);

return [{
  json: {
    skip: false,
    chatId,
    requestId,
    sessionId: uuidFrom(`telegram-session:${String(chatId)}`),
    message: asked
  }
}];

// Telegram is sent as plain text on purpose. Its Markdown parsers reject an
// unbalanced asterisk or an unescaped bracket with a 400, which would lose the
// whole answer over a stray character the agent had no way to predict.
//
// The hard limit is 4096 characters; the answer is cut a little short of it so
// the note about being cut still fits.
const reply = String($json.reply ?? $json.errorMessage ?? '').trim();

let text = reply.length === 0
  ? 'Your agent did not have an answer for that one.'
  : reply;

if (text.length > 3900) {
  text = text.slice(0, 3900) + '\n\n[cut short here - open your agent to read the rest]';
}

return [{ json: { chatId: $('Read The Message').item.json.chatId, text } }];
